mapper.select:
SELECT p.id, p.title, p.slug, p.summary, p.cover_url, p.content_html, p.toc_json, p.author_id, p.category_id, p.status, p.is_pinned AS pinned, p.pinned_at, p.published_at, p.like_count, p.view_count, COALESCE(comment_stats.comment_count, 0) AS comment_count, p.deleted_at, p.created_at, p.updated_at FROM posts p LEFT JOIN ( SELECT post_id, COUNT(*) as comment_count FROM comments WHERE status = 1 GROUP BY post_id ) comment_stats ON p.id = comment_stats.post_id
p.deleted_at IS NULL
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.summary LIKE CONCAT('%', #{keyword}, '%'))
AND p.category_id = #{categoryId}
AND p.status = #{status}
AND p.is_pinned = #{pinned}
ORDER BY p.is_pinned DESC, p.published_at DESC, p.id DESC

SELECT

FROM posts

    deleted_at IS NULL

        AND (title LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%'))


        AND status = #{status}


        AND category_id IN (
            SELECT id FROM categories WHERE slug = #{categorySlug}
        )


        AND author_id = #{authorId}




        ORDER BY ${orderBy}


        ORDER BY updated_at DESC, id DESC
